const fs=require("fs");
const src=fs.readFileSync("prisma/seed-blog-gaming.ts","utf8");
// match body: `...` where closing is backtick followed by ,\n (end of property)
const re=/body:\s*`([\s\S]*?)`,\n  },/g;
let m,counts=[];
while((m=re.exec(src))){counts.push(m[1].trim().split(/\s+/).length);}
